entries.content:
游戏的宠爪屋总控台，分别有着各式各样的功能，
当玩家选择返回宠爪屋总控台的时候会生成这个UI

<!DOCTYPE html>
<html lang="zh-CN">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>宠爪屋 | 总控制台</title>
<style>
    @import url('https://fonts.googleapis.com/css2?family=Orbitron:wght@500;700&family=Noto+Sans+SC:wght@300;400;700&display=swap');

    :root {
        --primary-color: #ffd700; /* 奢华的金色 */
        --secondary-color: #d4c2a8; /* 优雅的亚麻色 */
        --background-color: #1a1a1a;
        --container-bg-color: #262626;
        --border-color: #5a4b3c;
        --text-color: #e0e0e0;
        --hover-glow-color: rgba(255, 215, 0, 0.5);
    }

    body {
        background-color: var(--background-color);
        color: var(--text-color);
        font-family: 'Noto Sans SC', sans-serif;
        display: flex;
        justify-content: center;
        align-items: center;
        min-height: 100vh;
        margin: 0;
        padding: 20px;
        box-sizing: border-box;
        overflow: hidden; /* 隐藏滚动条以增强沉浸感 */
        background-image: radial-gradient(circle at center, rgba(40, 40, 40, 0.8), #1a1a1a 70%);
    }

    .main-console {
        width: 100%;
        max-width: 1200px; /* 增加宽度以容纳更多卡片 */
        background: linear-gradient(145deg, #2a2a2a, #1f1f1f);
        border: 2px solid var(--border-color);
        border-radius: 25px;
        box-shadow: 0 0 50px rgba(0, 0, 0, 0.8), inset 0 0 20px rgba(255, 215, 0, 0.1);
        display: flex;
        flex-direction: column;
        overflow: hidden;
    }

    .console-header {
        padding: 25px;
        text-align: center;
        background-color: #111;
        border-bottom: 2px solid var(--border-color);
    }

    .console-header h1 {
        margin: 0;
        font-family: 'Orbitron', sans-serif;
        font-size: 3.5em;
        color: var(--primary-color);
        text-shadow: 0 0 10px var(--hover-glow-color), 0 0 20px var(--hover-glow-color);
        letter-spacing: 3px;
    }

     .console-header .subtitle {
        font-size: 1.3em;
        color: var(--secondary-color);
        margin-top: 10px;
        font-style: italic;
        opacity: 0.8;
    }

    .kennel-selection-grid {
        display: grid;
        /* 调整为更灵活的布局，以适应不同数量的卡片 */
        grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
        gap: 30px;
        padding: 40px;
    }

    .kennel-card {
        background-color: var(--container-bg-color);
        border: 1px solid #444;
        border-radius: 15px;
        padding: 25px;
        text-align: center;
        cursor: pointer;
        transition: all 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
        position: relative;
        overflow: hidden;
    }

    .kennel-card::before {
        content: '';
        position: absolute;
        top: -50%;
        left: -50%;
        width: 200%;
        height: 200%;
        background: radial-gradient(circle, rgba(255, 215, 0, 0.15) 0%, rgba(255, 215, 0, 0) 70%);
        transform: rotate(0deg);
        transition: transform 0.5s ease;
        opacity: 0;
    }

    .kennel-card:hover {
        transform: translateY(-10px) scale(1.05);
        box-shadow: 0 15px 30px rgba(0, 0, 0, 0.5), 0 0 25px var(--hover-glow-color);
        border-color: var(--primary-color);
    }

    .kennel-card:hover::before {
        opacity: 1;
        transform: rotate(360deg);
    }

    .kennel-icon {
        font-size: 4.5em;
        margin-bottom: 15px;
        transition: transform 0.3s ease;
    }

    .kennel-card:hover .kennel-icon {
        transform: scale(1.1);
        text-shadow: 0 0 15px var(--hover-glow-color);
    }

    .kennel-title {
        font-family: 'Noto Sans SC', sans-serif;
        font-size: 1.8em;
        font-weight: 700;
        margin: 0;
        color: var(--secondary-color);
    }

    .kennel-id {
        font-family: 'Orbitron', sans-serif;
        font-size: 1.2em;
        font-weight: 500;
        color: var(--primary-color);
        margin-top: 10px;
        background-color: rgba(0,0,0,0.3);
        padding: 5px 15px;
        border-radius: 20px;
        display: inline-block;
    }

    .console-footer {
        margin-top: auto;
        padding: 20px;
        text-align: center;
        background-color: #111;
        border-top: 2px solid var(--border-color);
        font-size: 1em;
        color: #888;
    }

</style>
</head>
<body>

<div class="main-console">
    <div class="console-header">
        <h1>🐾 宠爪屋总控台 🐾</h1>
        <p class="subtitle">尊贵的会员，请输入相应的编号以进入指定专区</p>
    </div>

    <div class="kennel-selection-grid">
        <!-- 东方犬舍 -->
        <div class="kennel-card" onclick="selectKennel('01')">
            <div class="kennel-icon">🏯</div>
            <h2 class="kennel-title">东方犬舍</h2>
            <p class="kennel-id">[ 专区编号: 01 ]</p>
        </div>

        <!-- 西方犬舍 -->
        <div class="kennel-card" onclick="selectKennel('02')">
            <div class="kennel-icon">🏛️</div>
            <h2 class="kennel-title">西方犬舍</h2>
            <p class="kennel-id">[ 专区编号: 02 ]</p>
        </div>

        <!-- 拉丁犬舍 -->
        <div class="kennel-card" onclick="selectKennel('03')">
            <div class="kennel-icon">🌴</div>
            <h2 class="kennel-title">拉丁犬舍</h2>
            <p class="kennel-id">[ 专区编号: 03 ]</p>
        </div>

        <!-- 外科改造中心 -->
        <div class="kennel-card" onclick="selectKennel('04')">
            <div class="kennel-icon">🧬</div>
            <h2 class="kennel-title">改造中心</h2>
            <p class="kennel-id">[ 专区编号: 04 ]</p>
        </div>

        <!-- 赛犬区 -->
        <div class="kennel-card" onclick="selectKennel('05')">
            <div class="kennel-icon">🏆</div>
            <h2 class="kennel-title">赛犬区</h2>
            <p class="kennel-id">[ 专区编号: 05 ]</p>
        </div>

    </div>

    <div class="console-footer">
        © 宠爪宠物基地 | 专为顶级品味者服务
    </div>
</div>

